({
  async init(msg) {
    this.data = this.data || {};
    this._checkInvariants();
    return { ok: true };
  },

  _checkInvariants() {
    this.invariant(this.data !== null && typeof this.data === "object", "this.data must be an object");
  },

  async paginate(msg) {
    this.ensure(msg && typeof msg === "object", "Message must be an object");
    const payload = msg.payload || {};
    const { items, page = 1, pageSize = 10 } = payload;

    this.ensure(Array.isArray(items), "payload.items must be an array");
    this.ensure(typeof page === "number" && Number.isInteger(page) && page >= 1, "payload.page must be an integer >= 1");
    this.ensure(typeof pageSize === "number" && Number.isInteger(pageSize) && pageSize >= 1, "payload.pageSize must be an integer >= 1");

    const totalItems = items.length;
    const totalPages = Math.ceil(totalItems / pageSize);
    const startIndex = (page - 1) * pageSize;
    const paginatedItems = items.slice(startIndex, startIndex + pageSize);

    const hasNext = page < totalPages;
    const hasPrev = page > 1;

    const result = {
      items: paginatedItems,
      page,
      pageSize,
      totalItems,
      totalPages,
      hasNext,
      hasPrev
    };

    this.ensure(Array.isArray(result.items), "result.items must be an array");
    this.ensure(result.totalItems === totalItems, "result.totalItems must match input item count");
    this.ensure(result.totalPages === totalPages, "result.totalPages must match calculated total pages");
    this.ensure(typeof result.hasNext === "boolean", "result.hasNext must be a boolean");
    this.ensure(typeof result.hasPrev === "boolean", "result.hasPrev must be a boolean");

    this._checkInvariants();
    return result;
  },

  async ask(msg) {
    return {
      name: "PaginationHelper",
      description: "Utility object for paginating array items and computing navigation metrics.",
      methods: {
        paginate: "Paginates an array. Payload: { items: Array, page?: number, pageSize?: number } -> { items, page, pageSize, totalItems, totalPages, hasNext, hasPrev }"
      }
    };
  }
})
